package main

import (
	"log"
	"net"
	"net/http"
	"strings"
)

// extractFirstMatchFromIPList extracts the first IP address from a comma-separated list.
// It returns an empty string if the input is empty.
func extractFirstMatchFromIPList(ipList string) string {
	if ipList == "" {
		return ""
	}

	// Split the IP list by comma and get the first element
	ips := strings.Split(ipList, ",")
	if len(ips) == 0 {
		return ""
	}

	// Trim any whitespace from the IP address
	return strings.TrimSpace(ips[0])
}

func parseForwardedHeader(fwd string) string {
	splits := strings.Split(fwd, ";")
	if len(splits) == 0 {
		return ""
	}

	// The first part is the "for=" parameter
	first := splits[0]
	parts := strings.Split(first, "=")
	if len(parts) < 2 {
		return ""
	}
	return strings.TrimSpace(parts[1])
}

func getClientIP(r *http.Request) string {
	// Check X-Forwarded-For header first
	if fwd := r.Header.Get("X-Forwarded-For"); fwd != "" {
		return extractFirstMatchFromIPList(fwd)
	}

	// Check Forwarded header
	if fwd := r.Header.Get("Forwarded"); fwd != "" {
		return parseForwardedHeader(fwd)
	}

	// Fall back to RemoteAddr
	host, _, err := net.SplitHostPort(r.RemoteAddr)
	if err != nil {
		return r.RemoteAddr
	}
	return host
}

func main() {
	http.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		ip := getClientIP(r)
		w.Write([]byte(ip))
	})
	log.Fatal(http.ListenAndServe(":8080", nil))
}
