public class AuthConfigReproTest {

    @Test
    public void testWithEmailFluent() {
        AuthConfig config = new AuthConfig();
        AuthConfig returned = config.withEmail("test@example.com");
        assertSame(returned, config, "withEmail should return the same instance");
        assertEquals(config.getEmail(), "test@example.com");
    }

    @Test
    public void testWithPasswordFluent() {
        AuthConfig config = new AuthConfig();
        AuthConfig returned = config.withPassword("secret");
        assertSame(returned, config, "withPassword should return the same instance");
        assertEquals(config.getPassword(), "secret");
    }

    @Test
