        assertSame(returned, config, "withRegistryAddress should return the same instance");
        assertEquals(config.getRegistryAddress(), "localhost:5000");
    }

    @Test
    public void testMethodChaining() {
        AuthConfig config = new AuthConfig()
            .withEmail("test@example.com")
            .withPassword("secret")
            .withUsername("user1")
