// ProtoGetter is the interface that must be implemented by peer nodes.
type ProtoGetter interface {
	Get(ctx context.Context, in *pb.GetRequest, out *pb.GetResponse) error
}

// PeerPicker is the interface that must be implemented to locate
// the peer that owns a specific key.
type PeerPicker interface {
	PickPeer(key string) (ProtoGetter, bool)
}

type peerPicker func(key string) (ProtoGetter, bool)

var (
	portPicker atomic.Value // of type peerPicker
)

func RegisterPeerPicker(fn func(key string) (ProtoGetter, bool)) {
	portPicker.Store(peerPicker(fn))
}

func getPortPicker() peerPicker {
	p, _ := portPicker.Load().(peerPicker)
	return p
}
