	mainCache cache

	// hotCache contains keys that are served by another peer,
	// but are popular enough that we cache them locally.
	hotCache cache

	// loadGroup ensures that each key is only fetched
	// (on cache miss) once, either locally or from a peer.
	loadGroup flightGroup

	// Stats are statistics on the group.
	Stats Stats
}

// Getter loads data for a key.
type Getter interface {
	Get(ctx context.Context, key string, dest Sink) error
}

// GetterFunc implements Getter with a function.
type GetterFunc func(ctx context.Context, key string, dest Sink) error

// Get implements Getter interface function
func (f GetterFunc) Get(ctx context.Context, key string, dest Sink) error {
	return f(ctx, key, dest)
}

var (
	mu     sync.RWMutex
	groups = make(map[string]*Group)

	initPeerServerOnce sync.Once
	initPeerServer     func()
)

// GetGroup returns the named group previously created with NewGroup, or
// nil if there's no such group.
func GetGroup(name string) *Group {
	mu.RLock()
	g := groups[name]
	mu.RUnlock()
	return g
}

// NewGroup creates and returns a new Group of peers, and registers it.
func NewGroup(name string, cacheBytes int64, getter Getter) *Group {
	return newGroup(name, cacheBytes, getter, nil)
}

// NewGroup creates and returns a new Group of peers, and registers it.
func NewSingleFlightGroup(name string, cacheBytes int64, getter Getter) *Group {
	return newGroup(name, cacheBytes, getter, &singleflight.Group{})
}

// NewGroup creates and returns a new Group of peers, and registers it.
func NewSingleFlightGroupWithContext(name string, cacheBytes int64, getter Getter) *Group {
	return newGroup(name, cacheBytes, getter, &singleflight.Group{})
}

// NewGroup creates and returns a new Group of peers, and registers it.
func NewSingleFlightGroupWithContextAndName(name string, cacheBytes int64, getter Getter) *Group {
	return newGroup(name, cacheBytes, getter, &singleflight.Group{})
}

func newGroup(name string, cacheBytes int64, getter Getter, flightGroup flightGroup) *Group {
	if getter == nil {
		panic("nil Getter")
	}
	mu.Lock()
	defer mu.Unlock()
	initPeerServerOnce.Do(initPeerServer)
	if _, dup := groups[name]; dup {
		panic("duplicate registration of group " + name)
	}
	g := &Group{
		name:         name,
		getter:       getter,
		peersOnce:    sync.Once{},
		cacheBytes:   cacheBytes,
		loadGroup:    flightGroup,
		mainCache:    cache{},
		hotCache:     cache{},
	}
	if g.loadGroup == nil {
		g.loadGroup = &singleflight.Group{}
	}
	groups[name] = g
	return g
}

// RegisterPeerPicker registers the PeerPicker for the package.
func RegisterPeerPicker(fn func(key string) (ProtoGetter, bool)) {
	portPicker.Store(peerPicker(fn))
}

// Get is the cache get operation.
func (g *Group) Get(ctx context.Context, key string, dest Sink) error {
	dest = copySink(dest)
	if dest == nil {
		return errors.New("groupcache: nil dest Sink")
	}
	value, destPopulated, err := g.load(ctx, key, dest)
	if err != nil {
		return err
	}
	if destPopulated {
		return nil
	}
	return g.populateCache(ctx, key, value, dest)
}

func (g *Group) load(ctx context.Context, key string, dest Sink) (value ByteView, destPopulated bool, err error) {
	g.peersOnce.Do(func() {
		g.peers = getPortPicker()
	})
	if g.peers != nil {
		if peer, ok := g.peers.PickPeer(key); ok {
			if err := g.getFromPeer(ctx, peer, key, dest); err == nil {
				return
			}
		}
	}
	// ... rest of load
	return g.getLocally(ctx, key, dest)
}
